const http = require('http');
const express = require('express');
const { WebSocketServer } = require('ws');
const jwt = require('jsonwebtoken');
const { tradeBus } = require('../services/tradeBus');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', (request, socket, head) => {
  const url = new URL(request.url, `http://${request.headers.host}`);
  const token = url.searchParams.get('token');

  let verifiedUser;
  try {
    verifiedUser = jwt.verify(token, process.env.JWT_SECRET);
  } catch (err) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(request, socket, head, (ws) => {
    // Bind tenantId strictly to verified JWT claims
    ws.tenantId = verifiedUser.tenantId;
    wss.emit('connection', ws, request);
  });
});

wss.on('connection', (ws) => {
  const listener = (fillData) => {
    if (ws.readyState === ws.OPEN) {
      ws.send(JSON.stringify(fillData));
    }
  };
  tradeBus.on(`fills:${ws.tenantId}`, listener);
  ws.on('close', () => tradeBus.off(`fills:${ws.tenantId}`, listener));
});

server.listen(8080);
